import{_ as o,o as a,c as n,a2 as s}from"./chunks/framework.1C62pOns.js";const u=JSON.parse('{"title":"Conhecimento — expressões do pipeline","description":"","frontmatter":{},"headers":[],"relativePath":"pt/funcoes/conhecimento_pipeline.md","filePath":"pt/funcoes/conhecimento_pipeline.md","lastUpdated":1787839708000}'),t={name:"pt/funcoes/conhecimento_pipeline.md"};function i(r,e,p,d,c,l){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="conhecimento-—-expressoes-do-pipeline" tabindex="-1">Conhecimento — expressões do pipeline <a class="header-anchor" href="#conhecimento-—-expressoes-do-pipeline" aria-label="Permalink to &quot;Conhecimento — expressões do pipeline&quot;">​</a></h1><p>Os três campos Python da aba <strong>Processamento</strong> de um Conhecimento, usados na ingestão a partir de uma consulta SQL.</p><p><strong>Nenhuma função da plataforma está disponível aqui</strong> — as expressões rodam em um escopo vazio. O que você define na <em>Declaração do pipeline</em> (funções, constantes) fica visível para as outras duas, que são avaliadas uma vez por linha.</p><ul><li><strong>Declaração do pipeline</strong> — executada uma vez, antes da ingestão. Use para <code>import</code>, funções auxiliares e acumuladores.</li><li><strong>Conteúdo do documento</strong> — uma expressão que devolve o texto a vetorizar.</li><li><strong>Metadados do documento</strong> — uma expressão que devolve um dicionário.</li></ul><p>Estão disponíveis <strong>1</strong> símbolos neste contexto.</p><h2 id="outros" tabindex="-1">Outros <a class="header-anchor" href="#outros" aria-label="Permalink to &quot;Outros&quot;">​</a></h2><h3 id="row" tabindex="-1"><code>row</code> <a class="header-anchor" href="#row" aria-label="Permalink to &quot;`row`&quot;">​</a></h3><p><em>Não é uma função: já vem pronto no escopo.</em></p><p>A linha corrente da consulta, como dicionário: <code>row.get(&#39;nome&#39;)</code>. Só existe nas expressões de conteúdo e de metadados — na Declaração do pipeline ela ainda não foi lida.</p>',9)])])}const h=o(t,[["render",i]]);export{u as __pageData,h as default};
